    18	function ButtonWithDropdownMenu<IValueType>({
    19	    success = false,
    20	    isSplitButton = true,
    21	    isLoading = false,
    22	    isDisabled = false,
    23	    pressOnEnter = false,
    24	    shouldAlwaysShowDropdownMenu = false,
    25	    menuHeaderText = '',
    26	    customText,
    27	    style,
    28	    disabledStyle,
    29	    buttonSize = CONST.DROPDOWN_BUTTON_SIZE.MEDIUM,
    30	    anchorAlignment = {
    31	        horizontal: CONST.MODAL.ANCHOR_ORIGIN_HORIZONTAL.RIGHT,
    32	        vertical: CONST.MODAL.ANCHOR_ORIGIN_VERTICAL.TOP, // we assume that popover menu opens below the button, anchor is at TOP
    33	    },
    34	    buttonRef,
    35	    onPress,
    36	    options,
    37	    onOptionSelected,
    38	    onOptionsMenuShow,
    39	    onOptionsMenuHide,
    40	    enterKeyEventListenerPriority = 0,
    41	    wrapperStyle,
    42	    useKeyboardShortcuts = false,
    43	    shouldUseStyleUtilityForAnchorPosition = false,
    44	    defaultSelectedIndex = 0,
    45	    shouldShowSelectedItemCheck = false,
    46	}: ButtonWithDropdownMenuProps<IValueType>) {
    47	    const theme = useTheme();
    48	    const styles = useThemeStyles();
    49	    const StyleUtils = useStyleUtils();
    50	    const [selectedItemIndex, setSelectedItemIndex] = useState(defaultSelectedIndex);
    51	    const [isMenuVisible, setIsMenuVisible] = useState(false);
    52	    const [popoverAnchorPosition, setPopoverAnchorPosition] = useState<AnchorPosition | null>(null);
    53	    const {windowWidth, windowHeight} = useWindowDimensions();
    54	    const dropdownAnchor = useRef<View | null>(null);
    55	    const dropdownButtonRef = isSplitButton ? buttonRef : mergeRefs(buttonRef, dropdownAnchor);
    56	    const selectedItem = options[selectedItemIndex] || options[0];
    57	    const innerStyleDropButton = StyleUtils.getDropDownButtonHeight(buttonSize);
    58	    const isButtonSizeLarge = buttonSize === CONST.DROPDOWN_BUTTON_SIZE.LARGE;
    59	    const nullCheckRef = (ref: MutableRefObject<View | null>) => ref ?? null;
    60	
    61	    useEffect(() => {
    62	        if (!dropdownAnchor.current) {
    63	            return;
    64	        }
    65	        if (!isMenuVisible) {
    66	            return;
    67	        }
    68	        if ('measureInWindow' in dropdownAnchor.current) {
    69	            dropdownAnchor.current.measureInWindow((x, y, w, h) => {
    70	                setPopoverAnchorPosition({
    71	                    horizontal: x + w,
    72	                    vertical:
    73	                        anchorAlignment.vertical === CONST.MODAL.ANCHOR_ORIGIN_VERTICAL.TOP
    74	                            ? y + h + CONST.MODAL.POPOVER_MENU_PADDING // if vertical anchorAlignment is TOP, menu will open below the button and we need to add the height of button and padding
    75	                            : y - CONST.MODAL.POPOVER_MENU_PADDING, // if it is BOTTOM, menu will open above the button so NO need to add height but DO subtract padding
    76	                });
    77	            });
    78	        }
    79	    }, [windowWidth, windowHeight, isMenuVisible, anchorAlignment.vertical]);
    80	
    81	    useKeyboardShortcut(
    82	        CONST.KEYBOARD_SHORTCUTS.CTRL_ENTER,
    83	        (e) => {
    84	            if (shouldAlwaysShowDropdownMenu || options.length) {
    85	                if (!isSplitButton) {
    86	                    setIsMenuVisible(!isMenuVisible);
    87	                    return;
    88	                }
    89	                onPress(e, selectedItem?.value);
    90	            } else {
    91	                onPress(e, options[0]?.value);
    92	            }
    93	        },
    94	        {
    95	            captureOnInputs: true,
    96	            shouldBubble: false,
    97	            isActive: useKeyboardShortcuts,
    98	        },
    99	    );
   100	    const splitButtonWrapperStyle = isSplitButton ? [styles.flexRow, styles.justifyContentBetween, styles.alignItemsCenter] : {};
   101	
   102	    return (
   103	        <View style={wrapperStyle}>
   104	            {shouldAlwaysShowDropdownMenu || options.length > 1 ? (
   105	                <View style={[splitButtonWrapperStyle, style]}>
   106	                    <Button
   107	                        success={success}
   108	                        pressOnEnter={pressOnEnter}
   109	                        ref={dropdownButtonRef}
   110	                        onPress={(event) => (!isSplitButton ? setIsMenuVisible(!isMenuVisible) : onPress(event, selectedItem.value))}
   111	                        text={customText ?? selectedItem.text}
   112	                        isDisabled={isDisabled || !!selectedItem?.disabled}
   113	                        isLoading={isLoading}
   114	                        shouldRemoveRightBorderRadius
   115	                        style={isSplitButton ? [styles.flex1, styles.pr0] : {}}
   116	                        large={buttonSize === CONST.DROPDOWN_BUTTON_SIZE.LARGE}
   117	                        medium={buttonSize === CONST.DROPDOWN_BUTTON_SIZE.MEDIUM}
   118	                        small={buttonSize === CONST.DROPDOWN_BUTTON_SIZE.SMALL}
   119	                        innerStyles={[innerStyleDropButton, !isSplitButton && styles.dropDownButtonCartIconView]}
   120	                        enterKeyEventListenerPriority={enterKeyEventListenerPriority}
   121	                        iconRight={Expensicons.DownArrow}
   122	                        shouldShowRightIcon={!isSplitButton}
   123	                        isSplitButton={isSplitButton}
   124	                    />
   125	
   126	                    {isSplitButton && (
   127	                        <Button
   128	                            ref={dropdownAnchor}
   129	                            success={success}
   130	                            isDisabled={isDisabled}
   131	                            style={[styles.pl0]}
   132	                            onPress={() => setIsMenuVisible(!isMenuVisible)}
   133	                            shouldRemoveLeftBorderRadius
   134	                            large={buttonSize === CONST.DROPDOWN_BUTTON_SIZE.LARGE}
   135	                            medium={buttonSize === CONST.DROPDOWN_BUTTON_SIZE.MEDIUM}
   136	                            small={buttonSize === CONST.DROPDOWN_BUTTON_SIZE.SMALL}
   137	                            innerStyles={[styles.dropDownButtonCartIconContainerPadding, innerStyleDropButton]}
   138	                            enterKeyEventListenerPriority={enterKeyEventListenerPriority}
   139	                        >
   140	                            <View style={[styles.dropDownButtonCartIconView, innerStyleDropButton]}>
   141	                                <View style={[success ? styles.buttonSuccessDivider : styles.buttonDivider]} />
   142	                                <View style={[isButtonSizeLarge ? styles.dropDownLargeButtonArrowContain : styles.dropDownMediumButtonArrowContain]}>
   143	                                    <Icon
   144	                                        medium={isButtonSizeLarge}
   145	                                        small={!isButtonSizeLarge}
   146	                                        src={Expensicons.DownArrow}
   147	                                        fill={success ? theme.buttonSuccessText : theme.icon}
   148	                                    />
   149	                                </View>
   150	                            </View>
   151	                        </Button>
   152	                    )}
   153	                </View>
   154	            ) : (
   155	                <Button
   156	                    success={success}
   157	                    ref={buttonRef}
   158	                    pressOnEnter={pressOnEnter}
   159	                    isDisabled={isDisabled || !!options[0].disabled}
   160	                    style={[styles.w100, style]}
   161	                    disabledStyle={disabledStyle}
   162	                    isLoading={isLoading}
   163	                    text={selectedItem.text}
   164	                    onPress={(event) => onPress(event, options[0].value)}
   165	                    large={buttonSize === CONST.DROPDOWN_BUTTON_SIZE.LARGE}
   166	                    medium={buttonSize === CONST.DROPDOWN_BUTTON_SIZE.MEDIUM}
   167	                    small={buttonSize === CONST.DROPDOWN_BUTTON_SIZE.SMALL}
   168	                    innerStyles={[innerStyleDropButton]}
   169	                    enterKeyEventListenerPriority={enterKeyEventListenerPriority}
   170	                />
   171	            )}
   172	            {(shouldAlwaysShowDropdownMenu || options.length > 1) && popoverAnchorPosition && (
   173	                <PopoverMenu
   174	                    isVisible={isMenuVisible}
   175	                    onClose={() => {
   176	                        setIsMenuVisible(false);
   177	                        onOptionsMenuHide?.();
   178	                    }}
   179	                    onModalShow={onOptionsMenuShow}
   180	                    onItemSelected={() => setIsMenuVisible(false)}
   181	                    anchorPosition={shouldUseStyleUtilityForAnchorPosition ? styles.popoverButtonDropdownMenuOffset(windowWidth) : popoverAnchorPosition}
   182	                    shouldShowSelectedItemCheck={shouldShowSelectedItemCheck}
   183	                    anchorRef={nullCheckRef(dropdownAnchor)}
   184	                    withoutOverlay
   185	                    anchorAlignment={anchorAlignment}
   186	                    headerText={menuHeaderText}
   187	                    menuItems={options.map((item, index) => ({
   188	                        ...item,
   189	                        onSelected: item.onSelected
   190	                            ? () => item.onSelected?.()
   191	                            : () => {
   192	                                  onOptionSelected?.(item);
   193	                                  setSelectedItemIndex(index);
   194	                              },
   195	                        shouldCallAfterModalHide: true,
   196	                    }))}
   197	                />
   198	            )}
   199	        </View>
   200	    );
   201	}
